function selectBank(family: string, lessonNumber: number): TaskSeed[] {
  if (["cafe", "shop", "transport", "city", "home", "family", "study", "work", "time", "weather", "health", "finalreview"].includes(family)) return [];
  if (family === "morpheme") return banks.morpheme;
  if (family === "longword") return banks.longword;
  if (family === "phonetics") return banks.phonetics;
  if (family === "reading") return contextualBanks.reading;
  if (family === "vowels") return contextualBanks.vowels;
  if (family === "nominal") return banks.nominal;
  if (family === "barjoq") return banks.barjoq;
  if (family === "pronouns") return banks.pronouns;
  if (family === "intro") return banks.intro;
  if (family === "harmony") return banks.harmony;
  if (family === "locative") return banks.locative;
  if (family === "dative") return banks.dative;
  if (family === "ablative") return banks.ablative;
  if (family === "accusative") return banks.accusative;
  if (family === "instrumental") return banks.instrumental;
  if (family === "genitive") return banks.genitive;
  if (family === "possessive") return banks.possessive;
  if (family === "questions") return banks.questions;
  if (family === "verbs") return banks.verbs;
  if (family === "want") return banks.want;
  if (family === "need") return banks.need;
  if (family === "requests") return banks.requests;
  if (family === "system") return banks.system;
  return [];
}

function contextualFor(family: string): TaskSeed[] {
  if (family === "reading") return contextualBanks.reading;
  if (family === "phonetics") return contextualBanks.phonetics;
  if (family === "vowels") return [];
  if (family === "harmony") return contextualBanks.harmony;
  return contextualBanks[family] ?? [];
}

