function frameFor(family: string): { label: string; forms: [string, string][]; wrong: [string, string]; slot: [string, string] } {
  if (familyFrames[family]) return familyFrames[family];
  if (family === "translation") return familyFrames.translation;
  if (["reason", "opinion", "stories", "bridge"].includes(family)) return familyFrames[family];
  return familyFrames.verbs;
}

