function authoredLessonPractice(family: string): TaskSeed[] {
  const frame = frameFor(family);
  const context = practiceContexts[family];
  if (!context) throw new Error(`Missing authored practice context for ${family}`);
  const [first, second, third] = frame.forms;
  const normalizeOption = (value: string) => value.toLocaleLowerCase("uk").replace(/[.!?]+$/g, "").replace(/\s+/g, " ").trim();
  const uniqueOptions = (...items: string[]) => {
    const seen = new Set<string>();
    return items.filter((item) => {
      const key = normalizeOption(item);
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  };
  const parts = (value: string) => value.replace(/[.?]/g, "").split(" ");
  const productionTask = (form: [string, string]): TaskSeed => {
    const blocks = parts(form[0]);
    return blocks.length > 1
      ? { prompt: `${context.production} Склади казахською: “${form[1]}”.`, blocks, answer: blocks, skill: "form" }
      : { prompt: `${context.production} Напиши форму зі значенням “${form[1]}”.`, answer: form[0].replace(/[.?]/g, ""), skill: "writing" };
  };
  return [
    { prompt: `${context.setting} ${context.recognition} Що точно означає “${first[0]}”?`, options: uniqueOptions(first[1], second[1], third[1]), answer: first[1], skill: "meaning" },
    { prompt: `${context.recognition} Прочитай “${second[0]}” і вибери зміст.`, options: uniqueOptions(second[1], third[1], first[1]), answer: second[1], skill: "meaning" },
    { prompt: `${context.setting} Який зміст точно передає “${third[0]}”?`, options: uniqueOptions(third[1], first[1], second[1]), answer: third[1], skill: "meaning" },
    { prompt: `${context.production} Яка форма передає “${first[1]}”?`, options: uniqueOptions(first[0], second[0], third[0], frame.wrong[0]), answer: first[0], skill: "form" },
    { prompt: `${context.setting} Обери репліку або форму зі значенням “${second[1]}”.`, options: uniqueOptions(second[0], first[0], third[0], frame.wrong[0]), answer: second[0], skill: "form" },
    { prompt: `${context.recognition} Яка казахська форма передає “${third[1]}”?`, options: uniqueOptions(third[0], second[0], first[0], frame.wrong[0]), answer: third[0], skill: "form" },
    { prompt: `Доповни форму в контексті уроку: ${frame.slot[0]}`, answer: frame.slot[1], skill: "form" },
    { prompt: `Виправ реальну помилку “${frame.wrong[0]}”. Запиши лише нормативну форму.`, answer: frame.wrong[1], skill: "grammar" },
    { prompt: `Яке виправлення для “${frame.wrong[0]}” зберігає потрібний зміст?`, options: uniqueOptions(frame.wrong[1], frame.wrong[0], first[0], second[0]), answer: frame.wrong[1], skill: "grammar" },
    { prompt: `${context.recognition} Поєднай форми з точними значеннями.`, pairs: frame.forms, skill: "meaning" },
    productionTask(first),
    productionTask(second),
    productionTask(third),
    { prompt: `У якій парі казахська форма й український зміст справді збігаються?`, options: uniqueOptions(`${first[0]} — ${first[1]}`, `${first[0]} — ${second[1]}`, `${second[0]} — ${third[1]}`, `${third[0]} — ${first[1]}`), answer: `${first[0]} — ${first[1]}`, skill: "meaning" },
    { prompt: `Знайди пару з хибним перекладом.`, options: uniqueOptions(`${first[0]} — ${first[1]}`, `${second[0]} — ${second[1]}`, `${third[0]} — ${first[1]}`, `${third[0]} — ${third[1]}`), answer: `${third[0]} — ${first[1]}`, skill: "meaning" },
    { prompt: `${context.dialogue} Яка репліка передає “${second[1]}”?`, options: uniqueOptions(second[0], third[0], frame.wrong[0], first[0]), answer: second[0], skill: "dialogue" },
    { prompt: `${context.dialogue} Якою казахською реплікою передати “${third[1]}”?`, options: uniqueOptions(third[0], second[0], first[0], frame.wrong[0]), answer: third[0], skill: "dialogue" },
    { prompt: `Зістав три значення з формами перед підсумком уроку.`, pairs: [[first[1], first[0]], [second[1], second[0]], [third[1], third[0]]], skill: "review" },
    { prompt: `${context.production} Напиши без блоків: “${second[1]}”.`, answer: second[0].replace(/[.?]+$/g, ""), skill: "writing" },
    { prompt: `${context.production} Віднови без підказки форму зі значенням “${third[1]}”.`, answer: third[0].replace(/[.?]+$/g, ""), skill: "writing" }
  ];
}

function seedsForLesson(lessonNumber: number, family: string): TaskSeed[] {
  const seen = new Set<string>();
  const candidates = [...selectBank(family, lessonNumber), ...contextualFor(family), ...authoredLessonPractice(family)];
  const unique = candidates.filter((seed) => {
    if (seed.options) {
      const normalized = seed.options.map((option) => option.toLocaleLowerCase("uk").replace(/[.!?]+$/g, "").replace(/\s+/g, " ").trim());
      if (seed.options.length < 2 || new Set(normalized).size !== seed.options.length) return false;
    }
    if (seed.blocks && seed.blocks.length < 2) return false;
    if (seed.pairs && seed.pairs.length < 2) return false;
    if (seen.has(seed.prompt)) return false;
    seen.add(seed.prompt);
    return true;
  });
  if (unique.length < 18) throw new Error(`Lesson ${lessonNumber} (${family}) has only ${unique.length} reviewed exercises`);
  const target = Math.min(unique.length, [20, 22, 24, 21][lessonNumber % 4]);
  return unique.slice(0, target);
}

function scrambledBlocks(blocks: string[] | undefined, lessonNumber: number, index: number) {
  if (!blocks || blocks.length < 2) return blocks;
  const copy = [...blocks];
  const shift = ((lessonNumber * 3 + index * 5) % (copy.length - 1)) + 1;
  const rotated = [...copy.slice(shift), ...copy.slice(0, shift)];
  return rotated.join("\u0000") === copy.join("\u0000") ? [...copy].reverse() : rotated;
}

function typeForSeed(seed: TaskSeed, index: number): Exercise["type"] {
  if (seed.pairs) return "matchPairs";
  if (seed.blocks) return /порядок|Збери|Склади/.test(seed.prompt) ? "buildSentence" : "orderParts";
  if (/Виправ/.test(seed.prompt)) return "correctMistake";
  if (/Заповни/.test(seed.prompt)) return "fillBlank";
  if (!seed.options && seed.answer) return "fillBlank";
  if (seed.options) {
    if (seed.skill === "dialogue") return "dialogueChoice";
    return seed.options.every((option) => option.length <= 18) ? "compactChoice" : "choice";
  }
  return "translationRecognition";
}

function promptForLesson(prompt: string, _lessonNumber: number, family: string) {
  const context = practiceContexts[family];
  if (/^Доповни форму/.test(prompt)) return `${context.production} ${prompt}`;
  if (/^(Виправ реальну помилку|Яке виправлення)/.test(prompt)) return `${context.recognition} ${prompt}`;
  if (/^(У якій парі|Знайди пару з хибним перекладом)/.test(prompt)) return `${context.setting} ${prompt}`;
  if (/^Зістав три значення/.test(prompt)) return `${context.production} ${prompt}`;
  if (/^Поєднай\./.test(prompt)) return `${context.recognition} ${prompt}`;
  if (/^Виправ:/.test(prompt)) return `${context.recognition} ${prompt}`;
  if (/^(Заповни:|Збери:)/.test(prompt)) return `${context.production} ${prompt}`;
  return prompt;
}

function wrongFeedbackFor(seed: TaskSeed) {
  if (Array.isArray(seed.answer)) {
    return `Не зовсім. Правильний порядок: ${seed.answer.join(" + ")}.`;
  }
  if (typeof seed.answer === "string" && seed.answer.trim()) {
    return `Не зовсім. Правильна форма: ${seed.answer}.`;
  }
  if (seed.pairs) {
    return "Не зовсім. Звір кожну казахську форму з її українським значенням.";
  }
  return "Не зовсім. Повернися до прикладу в уроці й спробуй ще раз.";
}

function reviewedTask(lessonNumber: number, family: string, index: number): Exercise {
  const lessonId = "lesson-" + lessonNumber;
  const bank = seedsForLesson(lessonNumber, family);
  const seed = bank[index];
  const type = typeForSeed(seed, index);
  return {
    id: `${lessonId}-task-${String(index + 1).padStart(2, "0")}`,
    lessonId,
    type,
    skill: seed.skill ?? (type === "dialogueChoice" ? "dialogue" : type === "translationRecognition" ? "meaning" : "grammar"),
    prompt: promptForLesson(seed.prompt, lessonNumber, family),
    options: seed.options,
    answer: seed.answer,
    blocks: scrambledBlocks(seed.blocks, lessonNumber, index),
    pairs: seed.pairs,
    modelAnswer: seed.modelAnswer,
    feedbackCorrect: correctFeedbackFor(seed, type),
    feedbackWrong: wrongFeedbackFor(seed),
    relatedVocabularyIds: seed.vocabulary ?? [],
    relatedGrammarIds: seed.grammar ?? [],
    reviewed: true
  };
}

function correctFeedbackFor(seed: TaskSeed, type: Exercise["type"]) {
  if (type === "matchPairs") return "Правильно. Усі форми поєднані зі своїм точним значенням.";
  if (type === "buildSentence" || type === "orderParts" || type === "buildWord") return `Правильно. Порядок відновлено: ${Array.isArray(seed.answer) ? seed.answer.join(" + ") : seed.answer}.`;
  if (type === "correctMistake") return `Правильно. Виправлена форма: ${seed.answer}.`;
  if (type === "fillBlank") return `Правильно. У цій позиції потрібна форма «${seed.answer}».`;
  return "Правильно. Форма й значення відповідають контексту уроку.";
}

export const exercises: Exercise[] = lessonPlan.flatMap((lesson) => {
  const bank = seedsForLesson(lesson[1], lesson[5]);
  return bank.map((_, index) => reviewedTask(lesson[1], lesson[5], index));
});

export const exercisesByLesson = exercises.reduce<Record<string, Exercise[]>>((acc, exercise) => {
  acc[exercise.lessonId] ??= [];
  acc[exercise.lessonId].push(exercise);
  return acc;
}, {});
